import { type ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import { AudioLines, Box, Cpu, ExternalLink, FolderOpen, HardDriveDownload, Loader2, MessageSquareText, Mic, RefreshCw, RotateCcw, Settings2, SlidersHorizontal, Trash2 } from "lucide-react";
import type { HuggingFaceFile, HuggingFaceModel, LlamaCppRelease, LlamaCppRuntimeStatus, ModelAssignment, ModelInfo, MuPDFRelease, MuPDFRuntimeStatus, PromptSettings, ProviderStatus, Settings, WhisperCppRelease, WhisperCppRuntimeStatus, WhisperModel, WhisperStatus } from "@/types/api";
import type { ThemeMode } from "@/App";
import { api } from "@/lib/bridge";
import { languages } from "@/lib/languages";
import { bytes } from "@/lib/utils";
import { useOperationStore } from "@/stores/workspace";
import { StyledSelect, type SelectOption } from "./StyledSelect";

type PromptKey = keyof PromptSettings;
type ModelRole = "translation" | "vision";
type SettingsSection = "general" | "models" | "runtime" | "speech" | "prompts";
type RuntimeRelease = LlamaCppRelease | WhisperCppRelease;
type RuntimeStatus = LlamaCppRuntimeStatus | WhisperCppRuntimeStatus;

const providerOptions: SelectOption[] = [{ value: "ollama", label: "Ollama" }, { value: "llamacpp", label: "llama.cpp" }];
const runtimeOptions: SelectOption[] = [{ value: "auto", label: "Auto (CUDA then CPU fallback)" }, { value: "cuda", label: "CUDA" }, { value: "cpu", label: "CPU" }];
const themeOptions: SelectOption[] = [{ value: "system", label: "System" }, { value: "light", label: "Light" }, { value: "dark", label: "Dark" }];
const speechLanguageOptions: SelectOption[] = [{ value: "auto", label: "Detect automatically" }, ...languages.map((language) => ({ value: language.code, label: `${language.name} · ${language.code.toUpperCase()}` }))];
const promptOptions: Array<SelectOption & { key: PromptKey; hint: string }> = [
  { key: "translation", value: "translation", label: "Translation", hint: "Used for text, documents, and recognized image text. Supports {{target_language}}." },
  { key: "detection", value: "detection", label: "Language detection", hint: "Used to detect source-language ISO codes." },
  { key: "ocr", value: "ocr", label: "OCR / Vision", hint: "Used by the configured OCR / vision model." },
  { key: "wordVariants", value: "wordVariants", label: "Alternatives", hint: "Used for contextual replacement phrases. Supports {{target_language}}; source text, unmarked context, and an exact <alt-selection> marker are added separately." },
];
const navItems: Array<{ id: SettingsSection; label: string; caption: string; Icon: typeof Settings2 }> = [
  { id: "general", label: "General", caption: "Inference and appearance", Icon: SlidersHorizontal },
  { id: "models", label: "Models", caption: "Assignments and GGUF", Icon: Box },
  { id: "runtime", label: "Runtime", caption: "llama.cpp, Whisper, and MuPDF", Icon: Cpu },
  { id: "speech", label: "Speech", caption: "Whisper and microphone", Icon: AudioLines },
  { id: "prompts", label: "Prompts", caption: "System instructions", Icon: MessageSquareText },
];
const emptyAssignment: ModelAssignment = { id: "", supportsVision: false };

export function SettingsView({ theme, onThemeChange }: { theme: ThemeMode; onThemeChange: (theme: ThemeMode) => void }) {
  const [settings, setSettings] = useState<Settings | null>(null);
  const [defaults, setDefaults] = useState<PromptSettings | null>(null);
  const [status, setStatus] = useState<ProviderStatus | null>(null);
  const [ollamaModels, setOllamaModels] = useState<ModelInfo[]>([]);
  const [localModels, setLocalModels] = useState<ModelInfo[]>([]);
  const [llamaStatus, setLlamaStatus] = useState<LlamaCppRuntimeStatus | null>(null);
  const [llamaReleases, setLlamaReleases] = useState<LlamaCppRelease[]>([]);
  const [whisperStatus, setWhisperStatus] = useState<WhisperStatus | null>(null);
  const [whisperRuntimeStatus, setWhisperRuntimeStatus] = useState<WhisperCppRuntimeStatus | null>(null);
  const [whisperReleases, setWhisperReleases] = useState<WhisperCppRelease[]>([]);
  const [mupdfStatus, setMuPDFStatus] = useState<MuPDFRuntimeStatus | null>(null);
  const [mupdfReleases, setMuPDFReleases] = useState<MuPDFRelease[]>([]);
  const [whisperModels, setWhisperModels] = useState<WhisperModel[]>([]); const [whisperModelsLoaded, setWhisperModelsLoaded] = useState(false);
  const [section, setSection] = useState<SettingsSection>("general");
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<HuggingFaceModel[]>([]);
  const [files, setFiles] = useState<HuggingFaceFile[]>([]);
  const [selectedRepo, setSelectedRepo] = useState("");
  const [selectedFile, setSelectedFile] = useState("");
  const [selectedProjection, setSelectedProjection] = useState("");
  const [pullName, setPullName] = useState("");
  const [selectedLlamaRelease, setSelectedLlamaRelease] = useState("");
  const [selectedWhisperRelease, setSelectedWhisperRelease] = useState("");
  const [selectedMuPDFRelease, setSelectedMuPDFRelease] = useState("");
  const [promptKey, setPromptKey] = useState<PromptKey>("translation");
  const [savedModelDir, setSavedModelDir] = useState("");
  const [savedWhisperDir, setSavedWhisperDir] = useState("");
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const progress = useOperationStore((state) => state.progress);

  const refresh = useCallback(async () => {
    setBusy("refresh"); setError("");
    try {
      const [settingsResult, defaultsResult, providerResult, ollamaResult, localResult, llamaRuntimeResult, whisperRuntimeResult, whisperStatusResult, mupdfRuntimeResult] = await Promise.allSettled([
        api.getSettings(), api.defaultPrompts(), api.providerStatus(), api.ollamaModels(), api.localModels(), api.llamaRuntimeStatus(), api.whisperRuntimeStatus(), api.whisperStatus(), api.mupdfRuntimeStatus(),
      ]);
      if (settingsResult.status !== "fulfilled" || defaultsResult.status !== "fulfilled") throw new Error("Could not load settings");
      setSettings(settingsResult.value);
      setDefaults(defaultsResult.value);
      setSavedModelDir(settingsResult.value.llamaCpp.modelDir ?? "");
      setSavedWhisperDir(settingsResult.value.whisperCpp.modelDir ?? "");
      setStatus(providerResult.status === "fulfilled" ? providerResult.value : null);
      setOllamaModels(ollamaResult.status === "fulfilled" && Array.isArray(ollamaResult.value) ? ollamaResult.value : []);
      setLocalModels(localResult.status === "fulfilled" && Array.isArray(localResult.value) ? localResult.value : []);
      setLlamaStatus(llamaRuntimeResult.status === "fulfilled" ? llamaRuntimeResult.value : null);
      setWhisperRuntimeStatus(whisperRuntimeResult.status === "fulfilled" ? whisperRuntimeResult.value : null);
      setMuPDFStatus(mupdfRuntimeResult.status === "fulfilled" ? mupdfRuntimeResult.value : null);
      setWhisperStatus(whisperStatusResult.status === "fulfilled" ? whisperStatusResult.value : null); setWhisperModelsLoaded(false);
    } catch (reason) { setError(message(reason, "Could not load settings")); }
    finally { setBusy(""); }
  }, []);

  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { if (section === "runtime" && (llamaReleases.length === 0 || whisperReleases.length === 0 || mupdfReleases.length === 0)) void loadRuntimes(); }, [section, llamaReleases.length, whisperReleases.length, mupdfReleases.length]);
  useEffect(() => { if (section === "speech" && !whisperModelsLoaded) void loadWhisperModels(); }, [section, whisperModelsLoaded]);

  const updateSettings = useCallback((transform: (current: Settings) => Settings) => setSettings((current) => current ? transform(current) : current), []);
  const loadRuntimes = async () => {
    setBusy("releases"); setError("");
    try {
      const [llama, whisper, mupdf] = await Promise.all([api.llamaReleases(), api.whisperReleases(), api.mupdfReleases()]);
      setLlamaReleases(Array.isArray(llama) ? llama : []); setWhisperReleases(Array.isArray(whisper) ? whisper : []); setMuPDFReleases(Array.isArray(mupdf) ? mupdf : []);
      setSelectedLlamaRelease((value) => value || llama[0]?.version || ""); setSelectedWhisperRelease((value) => value || whisper[0]?.version || ""); setSelectedMuPDFRelease((value) => value || mupdf[0]?.version || "");
    } catch (reason) { setError(message(reason, "Could not load runtime releases")); }
    finally { setBusy(""); }
  };
  const loadWhisperModels = async () => { setBusy("whisper-models"); setError(""); try { const models = await api.whisperModels(); setWhisperModels(Array.isArray(models) ? models : []); setWhisperModelsLoaded(true); } catch (reason) { setError(message(reason, "Could not load official Whisper models")); } finally { setBusy(""); } };
  const save = async () => { if (!settings) return; setBusy("save"); setError(""); try { await api.saveSettings(settings); await refresh(); } catch (reason) { setError(message(reason, "Could not save settings")); } finally { setBusy(""); } };
  const chooseLlamaDirectory = async () => { try { const path = await api.pickLlamaModelDirectory(); if (path) updateSettings((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, modelDir: path } })); } catch (reason) { setError(message(reason, "Could not choose llama.cpp model directory")); } };
  const chooseWhisperDirectory = async () => { try { const path = await api.pickWhisperModelDirectory(); if (path) updateSettings((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, modelDir: path } })); } catch (reason) { setError(message(reason, "Could not choose Whisper model directory")); } };
  const search = async () => { if (!query.trim()) return; setBusy("search"); setError(""); try { setResults(await api.searchHF(query)); } catch (reason) { setError(message(reason, "Hugging Face search failed")); } finally { setBusy(""); } };
  const chooseRepo = async (repository: string) => { setBusy("files"); setError(""); setSelectedRepo(repository); setSelectedFile(""); setSelectedProjection(""); try { setFiles(await api.hfFiles(repository)); } catch (reason) { setError(message(reason, "Could not load GGUF files")); } finally { setBusy(""); } };
  const installModel = async () => { if (!selectedRepo || !selectedFile || llamaDirectoryDirty) return; setBusy("install"); setError(""); try { await api.installHF({ repository: selectedRepo, modelFile: selectedFile, mmprojFile: selectedProjection || undefined }); setSelectedFile(""); await refresh(); } catch (reason) { setError(message(reason, "Model installation failed")); } finally { setBusy(""); } };
  const pull = async () => { if (!pullName.trim()) return; setBusy("pull"); setError(""); try { await api.pullOllama(pullName.trim()); setPullName(""); await refresh(); } catch (reason) { setError(message(reason, "Ollama pull failed")); } finally { setBusy(""); } };
  const installLlama = async (mode: "cpu" | "cuda") => { if (!selectedLlamaRelease) return; setBusy(`llama-${mode}`); setError(""); try { await api.installLlamaRuntime({ version: selectedLlamaRelease, mode }); const next = await api.llamaRuntimeStatus(); setLlamaStatus(next); updateSettings((current) => current.llamaCpp.runtimeVersion ? current : { ...current, llamaCpp: { ...current.llamaCpp, runtimeVersion: selectedLlamaRelease } }); } catch (reason) { setError(message(reason, "llama.cpp installation failed")); } finally { setBusy(""); } };
  const installWhisperRuntime = async (mode: "cpu" | "cuda") => { if (!selectedWhisperRelease) return; setBusy(`whisper-${mode}`); setError(""); try { await api.installWhisperRuntime({ version: selectedWhisperRelease, mode }); const next = await api.whisperRuntimeStatus(); setWhisperRuntimeStatus(next); updateSettings((current) => current.whisperCpp.runtimeVersion ? current : { ...current, whisperCpp: { ...current.whisperCpp, runtimeVersion: selectedWhisperRelease } }); } catch (reason) { setError(message(reason, "Whisper.cpp installation failed")); } finally { setBusy(""); } };
  const installMuPDFRuntime = async () => { if (!selectedMuPDFRelease) return; setBusy("mupdf"); setError(""); try { await api.installMuPDFRuntime({ version: selectedMuPDFRelease }); setMuPDFStatus(await api.mupdfRuntimeStatus()); updateSettings((current) => current.mupdf.version ? current : { ...current, mupdf: { ...current.mupdf, version: selectedMuPDFRelease } }); } catch (reason) { setError(message(reason, "MuPDF installation failed")); } finally { setBusy(""); } };
  const installWhisperModel = async (id: string) => { if (whisperDirectoryDirty) return; setBusy(`whisper-model-${id}`); setError(""); try { const installed = await api.installWhisperModel({ id }); updateSettings((current) => current.whisperCpp.model.id ? current : { ...current, whisperCpp: { ...current.whisperCpp, model: { id: installed.id, path: installed.path } } }); await refresh(); } catch (reason) { setError(message(reason, "Whisper model installation failed")); } finally { setBusy(""); } };
  const removeWhisperModel = async (id: string) => { setBusy(`whisper-delete-${id}`); setError(""); try { await api.deleteWhisperModel(id); await refresh(); } catch (reason) { setError(message(reason, "Could not remove Whisper model")); } finally { setBusy(""); } };
  const assignOllama = (role: ModelRole, id: string) => { const model = ollamaModels.find((candidate) => candidate.id === id); updateSettings((current) => ({ ...current, ollama: { ...current.ollama, [role]: model ? assignmentFrom(model) : emptyAssignment } })); };
  const assignLlama = (role: ModelRole, id: string) => { const model = localModels.find((candidate) => candidate.id === id); updateSettings((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, [role]: model ? assignmentFrom(model) : emptyAssignment } })); };

  const modelFileOptions = useMemo(() => files.filter((file) => !file.mmproj).map((file) => ({ value: file.name, label: `${file.name} · ${bytes(file.size)}` })), [files]);
  const projectionOptions = useMemo(() => [{ value: "", label: "No vision projection (text only)" }, ...files.filter((file) => file.mmproj).map((file) => ({ value: file.name, label: `${file.name} · ${bytes(file.size)}` }))], [files]);
  const currentPrompt = settings?.prompts[promptKey] ?? "";
  const promptOption = promptOptions.find((option) => option.key === promptKey) ?? promptOptions[0];
  const activeNav = navItems.find((item) => item.id === section) ?? navItems[0];
  const llamaDirectoryDirty = Boolean(settings && (settings.llamaCpp.modelDir ?? "") !== savedModelDir);
  const whisperDirectoryDirty = Boolean(settings && (settings.whisperCpp.modelDir ?? "") !== savedWhisperDir);

  return <section className="settings-workspace h-full min-h-0"><div className="settings-layout h-full min-h-0">
    <aside className="settings-sidebar"><div className="settings-sidebar-brand"><p className="text-xs font-medium uppercase tracking-[.16em] text-muted-foreground">Localize</p><p className="mt-1 text-lg font-semibold tracking-tight">Settings</p></div><nav className="settings-nav" aria-label="Settings categories">{navItems.map(({ id, label, caption, Icon }) => <button key={id} type="button" onClick={() => setSection(id)} data-active={section === id} className="settings-nav-item"><Icon className="size-4" /><span className="min-w-0"><span className="block text-sm font-medium">{label}</span><span className="block truncate text-xs text-muted-foreground">{caption}</span></span></button>)}</nav><p className="settings-sidebar-note">Changes are applied only after saving.</p></aside>
    <div className="settings-scroll min-w-0 flex-1 overflow-y-auto"><div className="mx-auto w-full max-w-5xl px-4 py-5 sm:px-6"><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-medium uppercase tracking-[.16em] text-muted-foreground">{activeNav.caption}</p><h1 className="mt-1 text-2xl font-semibold tracking-tight">{activeNav.label}</h1></div><div className="flex items-end gap-2"><button onClick={() => void refresh()} disabled={busy === "refresh"} className="app-button app-button-outline"><RefreshCw className={busy === "refresh" ? "size-4 animate-spin" : "size-4"} />Refresh</button><button onClick={() => void save()} disabled={!settings || busy === "save"} className="app-button app-button-primary">{busy === "save" && <Loader2 className="size-4 animate-spin" />}Save changes</button></div></div>
      {error && <p className="mb-4 rounded-md bg-red-500/10 p-3 text-sm text-destructive">{error}</p>}
      {settings && <>
        {section === "general" && <GeneralSettings settings={settings} status={status} theme={theme} onThemeChange={onThemeChange} onUpdate={updateSettings} />}
        {section === "models" && <ModelsSettings settings={settings} ollamaModels={ollamaModels} localModels={localModels} query={query} results={results} selectedRepo={selectedRepo} selectedFile={selectedFile} selectedProjection={selectedProjection} pullName={pullName} busy={busy} directoryDirty={llamaDirectoryDirty} progress={progress} onPickDirectory={() => void chooseLlamaDirectory()} onAssignOllama={assignOllama} onAssignLlama={assignLlama} onQueryChange={setQuery} onSearch={() => void search()} onChooseRepo={(repository) => void chooseRepo(repository)} onSelectedFile={setSelectedFile} onSelectedProjection={setSelectedProjection} onInstall={() => void installModel()} onPullName={setPullName} onPull={() => void pull()} onRemoveOllama={(model) => void (async () => { setBusy("delete-ollama"); try { await api.deleteOllamaModel(model.id); await refresh(); } catch (reason) { setError(message(reason, "Could not remove Ollama model")); } finally { setBusy(""); } })()} onRemoveLocal={(model) => void (async () => { setBusy("delete-local"); try { await api.deleteLocalModel(model.id); await refresh(); } catch (reason) { setError(message(reason, "Could not remove local model")); } finally { setBusy(""); } })()} modelFileOptions={modelFileOptions} projectionOptions={projectionOptions} />}
        {section === "runtime" && <div className="space-y-4"><RuntimeInstaller title="llama.cpp" settingsVersion={settings.llamaCpp.runtimeVersion ?? ""} status={llamaStatus} releases={llamaReleases} selectedRelease={selectedLlamaRelease} mode={settings.llamaCpp.runtimeMode} busy={busy} progress={progress} onRefresh={() => void loadRuntimes()} onReleaseChange={setSelectedLlamaRelease} onModeChange={(value) => updateSettings((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, runtimeMode: value as Settings["llamaCpp"]["runtimeMode"] } }))} onUse={(version) => updateSettings((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, runtimeVersion: version } }))} onInstall={(mode) => void installLlama(mode)} /><RuntimeInstaller title="Whisper.cpp" settingsVersion={settings.whisperCpp.runtimeVersion ?? ""} status={whisperRuntimeStatus} releases={whisperReleases} selectedRelease={selectedWhisperRelease} mode={settings.whisperCpp.runtimeMode} busy={busy} progress={progress} onRefresh={() => void loadRuntimes()} onReleaseChange={setSelectedWhisperRelease} onModeChange={(value) => updateSettings((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, runtimeMode: value as Settings["whisperCpp"]["runtimeMode"] } }))} onUse={(version) => updateSettings((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, runtimeVersion: version } }))} onInstall={(mode) => void installWhisperRuntime(mode)} /><MuPDFRuntimeInstaller settingsVersion={settings.mupdf.version ?? ""} status={mupdfStatus} releases={mupdfReleases} selectedRelease={selectedMuPDFRelease} busy={busy} progress={progress} onRefresh={() => void loadRuntimes()} onReleaseChange={setSelectedMuPDFRelease} onUse={(version) => updateSettings((current) => ({ ...current, mupdf: { ...current.mupdf, version } }))} onInstall={() => void installMuPDFRuntime()} /></div>}
        {section === "speech" && <SpeechSettings settings={settings} status={whisperStatus} models={whisperModels} busy={busy} progress={progress} directoryDirty={whisperDirectoryDirty} onUpdate={updateSettings} onChooseDirectory={() => void chooseWhisperDirectory()} onInstall={(id) => void installWhisperModel(id)} onRemove={(id) => void removeWhisperModel(id)} />}
        {section === "prompts" && <PromptSettingsCard currentPrompt={currentPrompt} promptKey={promptKey} promptOption={promptOption} defaults={defaults} onPromptKey={setPromptKey} onPromptChange={(value) => updateSettings((current) => ({ ...current, prompts: { ...current.prompts, [promptKey]: value } }))} onRestore={() => defaults && updateSettings((current) => ({ ...current, prompts: { ...current.prompts, [promptKey]: defaults[promptKey] } }))} />}
      </>}
    </div></div>
  </div></section>;
}

function GeneralSettings({ settings, status, theme, onThemeChange, onUpdate }: { settings: Settings; status: ProviderStatus | null; theme: ThemeMode; onThemeChange: (theme: ThemeMode) => void; onUpdate: (transform: (current: Settings) => Settings) => void }) {
  return <div className="space-y-4"><section className="surface p-4"><div className="mb-3 flex items-center justify-between"><div><h2 className="text-sm font-semibold">Provider status</h2><p className={status?.available ? "mt-1 text-xs text-muted-foreground" : "mt-1 text-xs text-destructive"}>{status?.message ?? "Checking provider…"}</p></div><span className="rounded-full border px-2 py-1 text-xs font-medium">{status?.provider === "llamacpp" ? "llama.cpp" : "Ollama"}</span></div></section><section className="surface p-4"><h2 className="mb-3 text-sm font-semibold">Inference</h2><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Active provider<StyledSelect className="mt-1" value={settings.activeProvider} onChange={(value) => onUpdate((current) => ({ ...current, activeProvider: value as Settings["activeProvider"] }))} options={providerOptions} placeholder="Choose provider" ariaLabel="Active provider" /></label><label className="text-xs font-medium text-muted-foreground">llama.cpp runtime mode<StyledSelect className="mt-1" value={settings.llamaCpp.runtimeMode} onChange={(value) => onUpdate((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, runtimeMode: value as Settings["llamaCpp"]["runtimeMode"] } }))} options={runtimeOptions} placeholder="Choose runtime" ariaLabel="llama.cpp runtime mode" /></label></div><label className="mt-3 block text-xs font-medium text-muted-foreground">Ollama endpoint<input value={settings.ollama.endpoint} onChange={(event) => onUpdate((current) => ({ ...current, ollama: { ...current.ollama, endpoint: event.target.value } }))} className="field mt-1" /></label><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Context size<input type="number" min="1024" max="131072" value={settings.llamaCpp.contextSize} onChange={(event) => onUpdate((current) => ({ ...current, llamaCpp: { ...current.llamaCpp, contextSize: Number(event.target.value) } }))} className="field mt-1" /></label><p className="self-end text-xs text-muted-foreground">Changing the llama.cpp runtime settings stops the Localize-owned process.</p></div></section><section className="surface p-4"><h2 className="mb-3 text-sm font-semibold">Appearance</h2><label className="block max-w-sm text-xs font-medium text-muted-foreground">Theme<StyledSelect className="mt-1" value={theme} onChange={(value) => onThemeChange(value as ThemeMode)} options={themeOptions} placeholder="System" ariaLabel="Appearance theme" /></label></section></div>;
}

function ModelsSettings({ settings, ollamaModels, localModels, query, results, selectedRepo, selectedFile, selectedProjection, pullName, busy, directoryDirty, progress, onPickDirectory, onAssignOllama, onAssignLlama, onQueryChange, onSearch, onChooseRepo, onSelectedFile, onSelectedProjection, onInstall, onPullName, onPull, onRemoveOllama, onRemoveLocal, modelFileOptions, projectionOptions }: { settings: Settings; ollamaModels: ModelInfo[]; localModels: ModelInfo[]; query: string; results: HuggingFaceModel[]; selectedRepo: string; selectedFile: string; selectedProjection: string; pullName: string; busy: string; directoryDirty: boolean; progress: ReturnType<typeof useOperationStore.getState>["progress"]; onPickDirectory: () => void; onAssignOllama: (role: ModelRole, id: string) => void; onAssignLlama: (role: ModelRole, id: string) => void; onQueryChange: (value: string) => void; onSearch: () => void; onChooseRepo: (repository: string) => void; onSelectedFile: (value: string) => void; onSelectedProjection: (value: string) => void; onInstall: () => void; onPullName: (value: string) => void; onPull: () => void; onRemoveOllama: (model: ModelInfo) => void; onRemoveLocal: (model: ModelInfo) => void; modelFileOptions: SelectOption[]; projectionOptions: SelectOption[] }) {
  return <div className="space-y-4"><section className="surface p-4"><div className="mb-3"><h2 className="text-sm font-semibold">Model assignments</h2><p className="mt-1 text-xs text-muted-foreground">Choose a model for each translation and OCR role before starting work.</p></div><div className="grid gap-3 lg:grid-cols-2"><AssignmentGroup title="Ollama" active={settings.activeProvider === "ollama"} models={ollamaModels} translation={settings.ollama.translation.id} vision={settings.ollama.vision.id} onAssign={onAssignOllama} emptyText="Pull an Ollama model below to assign it." /><AssignmentGroup title="llama.cpp" active={settings.activeProvider === "llamacpp"} models={localModels} translation={settings.llamaCpp.translation.id} vision={settings.llamaCpp.vision.id} onAssign={onAssignLlama} emptyText="Install a GGUF model below to assign it." /></div></section><section className="surface p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">llama.cpp model location</h2><p className="mt-1 text-xs text-muted-foreground">New GGUF files are installed here. Existing models are never moved automatically.</p></div><button onClick={onPickDirectory} className="app-button app-button-outline shrink-0"><FolderOpen className="size-4" />Choose folder</button></div><p className="rounded-md border bg-muted/25 px-3 py-2 font-mono text-xs text-muted-foreground break-all">{settings.llamaCpp.modelDir || "No folder selected"}</p>{directoryDirty && <p className="mt-2 text-xs text-amber-600 dark:text-amber-400">Save this folder before installing a model into it.</p>}</section><section className="surface p-4"><div className="flex items-center justify-between gap-3"><div><h2 className="text-sm font-semibold">Ollama models</h2><p className="text-xs text-muted-foreground">Use the official catalog for discovery, then pull by model name.</p></div><button onClick={() => void api.openOllamaCatalog()} className="app-button app-button-outline"><ExternalLink className="size-4" />Catalog</button></div><div className="mt-3 flex gap-2"><input value={pullName} onChange={(event) => onPullName(event.target.value)} placeholder="translategemma:latest" className="field" /><button onClick={onPull} disabled={!pullName.trim() || busy === "pull"} className="app-button app-button-primary">{busy === "pull" ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Pull</button></div>{ollamaModels.length > 0 ? <div className="mt-3 space-y-1">{ollamaModels.map((model) => <ModelRow key={model.id} model={model} action={<button onClick={() => onRemoveOllama(model)} disabled={busy === "delete-ollama"} className="app-button app-button-danger" aria-label={`Remove ${model.name || model.id}`}><Trash2 className="size-4" /></button>} />)}</div> : <p className="mt-3 text-xs text-muted-foreground">No installed Ollama models found.</p>}</section><section className="surface p-4"><h2 className="text-sm font-semibold">Hugging Face GGUF</h2><p className="mt-1 text-xs text-muted-foreground">Public non-gated GGUF repositories only. Add a vision projection when OCR is needed.</p>{progress?.kind === "huggingface-download" && <DownloadProgress progress={progress} className="mt-3" />}<div className="mt-3 flex gap-2"><input value={query} onChange={(event) => onQueryChange(event.target.value)} onKeyDown={(event) => event.key === "Enter" && onSearch()} placeholder="Search GGUF models" className="field" /><button onClick={onSearch} disabled={!query.trim() || busy === "search"} className="app-button app-button-primary">{busy === "search" ? <Loader2 className="size-4 animate-spin" /> : "Search"}</button></div>{results.length > 0 && <div className="mt-3 max-h-48 space-y-1 overflow-auto">{results.map((model) => <button key={model.id} onClick={() => onChooseRepo(model.id)} className={selectedRepo === model.id ? "block w-full rounded-md border bg-muted px-3 py-2 text-left" : "block w-full rounded-md border border-transparent px-3 py-2 text-left hover:bg-muted"}><span className="text-sm font-medium">{model.id}</span><span className="ml-2 text-xs text-muted-foreground">{model.downloads.toLocaleString()} downloads</span></button>)}</div>}{selectedRepo && <div className="mt-3 border-t pt-3"><p className="mb-2 text-xs font-medium text-muted-foreground">{selectedRepo}</p>{busy === "files" ? <LoadingLine /> : <><StyledSelect value={selectedFile} onChange={onSelectedFile} options={modelFileOptions} placeholder="Choose a model GGUF" ariaLabel="GGUF model file" /><StyledSelect className="mt-2" value={selectedProjection} onChange={onSelectedProjection} options={projectionOptions} placeholder="No vision projection" ariaLabel="Vision projection file" /><button onClick={onInstall} disabled={!selectedFile || busy === "install" || directoryDirty} className="app-button app-button-primary mt-2">{busy === "install" ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Install selected model</button></>}</div>}<div className="mt-4 border-t pt-3"><p className="mb-2 text-xs font-medium text-muted-foreground">Installed llama.cpp models</p>{localModels.length > 0 ? <div className="space-y-1">{localModels.map((model) => <ModelRow key={model.path ?? model.id} model={model} action={<button onClick={() => onRemoveLocal(model)} disabled={busy === "delete-local"} className="app-button app-button-danger" aria-label={`Remove ${model.name || model.id}`}><Trash2 className="size-4" /></button>} />)}</div> : <p className="text-xs text-muted-foreground">No managed GGUF files yet.</p>}</div></section></div>;
}

function MuPDFRuntimeInstaller({ settingsVersion, status, releases, selectedRelease, busy, progress, onRefresh, onReleaseChange, onUse, onInstall }: { settingsVersion: string; status: MuPDFRuntimeStatus | null; releases: MuPDFRelease[]; selectedRelease: string; busy: string; progress: ReturnType<typeof useOperationStore.getState>["progress"]; onRefresh: () => void; onReleaseChange: (value: string) => void; onUse: (version: string) => void; onInstall: () => void }) {
  const selected = releases.find((release) => release.version === selectedRelease); const installedOptions = [{ value: "", label: "No runtime selected" }, ...(status?.installed ?? []).map((item) => ({ value: item.version, label: item.version }))]; const releaseOptions = releases.map((release) => ({ value: release.version, label: `${release.version}${release.publishedAt ? ` · ${new Date(release.publishedAt).toLocaleDateString()}` : ""}` }));
  return <section className="surface p-4"><div className="mb-4 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">MuPDF document runtime</h2><p className="mt-1 text-xs text-muted-foreground">Not bundled with Localize. Choose an official Windows release to download into Localize data for document extraction and scanned-PDF rendering.</p></div><button onClick={onRefresh} disabled={busy === "releases"} className="app-button app-button-outline"><RefreshCw className={busy === "releases" ? "size-4 animate-spin" : "size-4"} />Reload</button></div>{progress?.kind === "mupdf-install" && <DownloadProgress progress={progress} className="mb-3" />}<label className="block max-w-xl text-xs font-medium text-muted-foreground">Installed version<StyledSelect className="mt-1" value={settingsVersion} onChange={onUse} options={installedOptions} placeholder="Install MuPDF below" ariaLabel="Selected MuPDF runtime version" /></label>{status && <p className="mt-3 rounded-md border bg-muted/25 px-3 py-2 font-mono text-xs text-muted-foreground break-all">Runtime files: {status.root}</p>}<div className="mt-4 border-t pt-4"><label className="block max-w-xl text-xs font-medium text-muted-foreground">Official Windows version<StyledSelect className="mt-1" value={selectedRelease} onChange={onReleaseChange} options={releaseOptions} placeholder="No compatible release found" ariaLabel="MuPDF release to install" /></label>{selected && <div className="mt-3 flex flex-wrap items-center gap-2 rounded-md border bg-muted/20 p-3"><span className="text-xs text-muted-foreground">Archive: {bytes(selected.artifact.size)}</span><a href="https://github.com/ArtifexSoftware/mupdf-downloads/releases" target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-xs text-muted-foreground underline-offset-2 hover:underline"><ExternalLink className="size-3" />Official releases</a><button onClick={onInstall} disabled={busy === "mupdf"} className="app-button app-button-primary ml-auto">{busy === "mupdf" ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Download and install</button></div>}</div>{status?.installed.length ? <div className="mt-4 border-t pt-4"><p className="text-xs font-medium text-muted-foreground">Installed versions</p><div className="mt-2 space-y-1">{status.installed.map((item) => <div key={item.version} className="flex flex-wrap items-center gap-2 rounded-md border px-3 py-2"><span className="text-sm font-medium">{item.version}</span><span className="rounded-full bg-muted px-2 py-0.5 text-xs">MuPDF</span><button onClick={() => onUse(item.version)} className="app-button app-button-outline ml-auto">{settingsVersion === item.version ? "Selected" : "Use this version"}</button></div>)}</div></div> : null}</section>;
}

function RuntimeInstaller({ title, settingsVersion, status, releases, selectedRelease, mode, busy, progress, onRefresh, onReleaseChange, onModeChange, onUse, onInstall }: { title: string; settingsVersion: string; status: RuntimeStatus | null; releases: RuntimeRelease[]; selectedRelease: string; mode: Settings["llamaCpp"]["runtimeMode"]; busy: string; progress: ReturnType<typeof useOperationStore.getState>["progress"]; onRefresh: () => void; onReleaseChange: (value: string) => void; onModeChange: (value: string) => void; onUse: (version: string) => void; onInstall: (mode: "cpu" | "cuda") => void }) {
  const selected = releases.find((release) => release.version === selectedRelease); const installedOptions = [{ value: "", label: "No runtime selected" }, ...(status?.installed ?? []).map((item) => ({ value: item.version, label: runtimeLabel(item) }))]; const releaseOptions = releases.map((release) => ({ value: release.version, label: `${release.version}${release.publishedAt ? ` · ${new Date(release.publishedAt).toLocaleDateString()}` : ""}` })); const kind = title === "Whisper.cpp" ? "whispercpp-install" : "llamacpp-install"; const busyPrefix = title === "Whisper.cpp" ? "whisper" : "llama";
  return <section className="surface p-4"><div className="mb-4 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">{title} runtime</h2><p className="mt-1 text-xs text-muted-foreground">Official archives are checksum-verified, resumable, and installed atomically in Localize data.</p></div><button onClick={onRefresh} disabled={busy === "releases"} className="app-button app-button-outline"><RefreshCw className={busy === "releases" ? "size-4 animate-spin" : "size-4"} />Reload</button></div>{progress?.kind === kind && <DownloadProgress progress={progress} className="mb-3" />}<div className="grid gap-3 md:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Installed version<StyledSelect className="mt-1" value={settingsVersion} onChange={onUse} options={installedOptions} placeholder="Install a runtime below" ariaLabel={`${title} selected runtime version`} /></label><label className="text-xs font-medium text-muted-foreground">Runtime mode<StyledSelect className="mt-1" value={mode} onChange={onModeChange} options={runtimeOptions} placeholder="Choose runtime mode" ariaLabel={`${title} runtime mode`} /></label></div>{status && <p className="mt-3 rounded-md border bg-muted/25 px-3 py-2 font-mono text-xs text-muted-foreground break-all">Runtime files: {status.root}</p>}<div className="mt-4 border-t pt-4"><label className="block max-w-xl text-xs font-medium text-muted-foreground">Official version<StyledSelect className="mt-1" value={selectedRelease} onChange={onReleaseChange} options={releaseOptions} placeholder="No compatible release found" ariaLabel={`${title} release to install`} /></label>{selected && <div className="mt-3 flex flex-wrap items-center gap-2 rounded-md border bg-muted/20 p-3"><span className="text-xs text-muted-foreground">CPU: {bytes(selected.cpu.size)}</span><span className="text-xs text-muted-foreground">CUDA: {selected.cuda.url ? bytes(selected.cuda.size) : "not published"}</span><button onClick={() => onInstall("cpu")} disabled={busy === `${busyPrefix}-cpu`} className="app-button app-button-primary ml-auto">{busy === `${busyPrefix}-cpu` ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Install CPU</button><button onClick={() => onInstall("cuda")} disabled={!selected.cuda.url || busy === `${busyPrefix}-cuda`} className="app-button app-button-outline">{busy === `${busyPrefix}-cuda` ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Install CUDA</button></div>}</div>{status?.installed.length ? <div className="mt-4 border-t pt-4"><p className="text-xs font-medium text-muted-foreground">Installed versions</p><div className="mt-2 space-y-1">{status.installed.map((item) => <div key={item.version} className="flex flex-wrap items-center gap-2 rounded-md border px-3 py-2"><span className="text-sm font-medium">{item.version}</span>{item.cpuInstalled && <span className="rounded-full bg-muted px-2 py-0.5 text-xs">CPU</span>}{item.cudaInstalled && <span className="rounded-full bg-muted px-2 py-0.5 text-xs">CUDA</span>}<button onClick={() => onUse(item.version)} className="app-button app-button-outline ml-auto">{settingsVersion === item.version ? "Selected" : "Use this version"}</button></div>)}</div></div> : null}</section>;
}

function SpeechSettings({ settings, status, models, busy, progress, directoryDirty, onUpdate, onChooseDirectory, onInstall, onRemove }: { settings: Settings; status: WhisperStatus | null; models: WhisperModel[]; busy: string; progress: ReturnType<typeof useOperationStore.getState>["progress"]; directoryDirty: boolean; onUpdate: (transform: (current: Settings) => Settings) => void; onChooseDirectory: () => void; onInstall: (id: string) => void; onRemove: (id: string) => void }) {
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]); const [deviceError, setDeviceError] = useState("");
  const refreshDevices = useCallback(async (requestPermission: boolean) => { try { if (!navigator.mediaDevices?.enumerateDevices) throw new Error("This WebView does not support microphone selection"); if (requestPermission) { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); stream.getTracks().forEach((track) => track.stop()); } const all = await navigator.mediaDevices.enumerateDevices(); setDevices(all.filter((device) => device.kind === "audioinput")); setDeviceError(""); } catch (reason) { setDeviceError(message(reason, "Microphone permission is required to list inputs")); } }, []);
  useEffect(() => { void refreshDevices(false); }, [refreshDevices]);
  const installed = models.filter((model) => model.installed); const modelOptions = [{ value: "", label: "No Whisper model selected" }, ...installed.map((model) => ({ value: model.id, label: `${model.id} · ${bytes(model.size)}` }))]; const deviceOptions = [{ value: "", label: "System default microphone" }, ...devices.map((device, index) => ({ value: device.deviceId, label: device.label || `Microphone ${index + 1}` }))];
  return <div className="space-y-4"><section className="surface p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">Whisper status</h2><p className={status?.available ? "mt-1 text-xs text-muted-foreground" : "mt-1 text-xs text-destructive"}>{status?.message ?? "Checking Whisper.cpp…"}</p></div><AudioLines className="mt-0.5 size-5 text-muted-foreground" /></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Transcription model<StyledSelect className="mt-1" value={settings.whisperCpp.model.id} onChange={(id) => { const model = installed.find((item) => item.id === id); onUpdate((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, model: model ? { id: model.id, path: model.path } : { id: "" } } })); }} options={modelOptions} placeholder="Install a Whisper model below" ariaLabel="Whisper transcription model" /></label><label className="text-xs font-medium text-muted-foreground">Spoken language<StyledSelect className="mt-1" value={settings.whisperCpp.language || "auto"} onChange={(language) => onUpdate((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, language } }))} options={speechLanguageOptions} placeholder="Detect automatically" ariaLabel="Whisper spoken language" /></label></div></section><section className="surface p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">Microphone</h2><p className="mt-1 text-xs text-muted-foreground">The selected input is used for recording and live transcription. Windows may ask for microphone permission.</p></div><button onClick={() => void refreshDevices(true)} className="app-button app-button-outline"><Mic className="size-4" />Allow / refresh</button></div><label className="block max-w-xl text-xs font-medium text-muted-foreground">Audio input<StyledSelect className="mt-1" value={settings.whisperCpp.microphoneId ?? ""} onChange={(microphoneId) => { const device = devices.find((item) => item.deviceId === microphoneId); onUpdate((current) => ({ ...current, whisperCpp: { ...current.whisperCpp, microphoneId, microphoneName: device?.label ?? "" } })); }} options={deviceOptions} placeholder="System default microphone" ariaLabel="Selected microphone" /></label>{settings.whisperCpp.microphoneName && !devices.some((device) => device.deviceId === settings.whisperCpp.microphoneId) && <p className="mt-2 text-xs text-amber-600 dark:text-amber-400">Previously selected: {settings.whisperCpp.microphoneName}. Reconnect it or choose another input.</p>}{deviceError && <p className="mt-2 text-xs text-destructive">{deviceError}</p>}</section><section className="surface p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">Whisper model location</h2><p className="mt-1 text-xs text-muted-foreground">Official multilingual models are downloaded here and verified against Hugging Face LFS hashes.</p></div><button onClick={onChooseDirectory} className="app-button app-button-outline shrink-0"><FolderOpen className="size-4" />Choose folder</button></div><p className="rounded-md border bg-muted/25 px-3 py-2 font-mono text-xs text-muted-foreground break-all">{settings.whisperCpp.modelDir || "No folder selected"}</p>{directoryDirty && <p className="mt-2 text-xs text-amber-600 dark:text-amber-400">Save this folder before installing a model into it.</p>}</section><section className="surface p-4"><div className="mb-3"><h2 className="text-sm font-semibold">Official Whisper models</h2><p className="mt-1 text-xs text-muted-foreground">Use multilingual models for Localize. English-only variants are marked clearly.</p></div>{progress?.kind === "whisper-model-download" && <DownloadProgress progress={progress} className="mb-3" />}<div className="space-y-1">{models.map((model) => <div key={model.id} className="flex flex-wrap items-center gap-2 rounded-md border px-3 py-2"><div className="min-w-0 flex-1"><p className="text-sm font-medium">{model.id} {!model.multilingual && <span className="text-xs font-normal text-muted-foreground">English only</span>}</p><p className="text-xs text-muted-foreground">{bytes(model.size)} · SHA-256 verified</p></div>{model.installed ? <><span className="rounded-full bg-muted px-2 py-0.5 text-xs">Installed</span><button onClick={() => onRemove(model.id)} disabled={busy === `whisper-delete-${model.id}`} className="app-button app-button-danger" aria-label={`Remove ${model.id}`}><Trash2 className="size-4" /></button></> : <button onClick={() => onInstall(model.id)} disabled={directoryDirty || busy === `whisper-model-${model.id}`} className="app-button app-button-primary">{busy === `whisper-model-${model.id}` ? <Loader2 className="size-4 animate-spin" /> : <HardDriveDownload className="size-4" />}Install</button>}</div>)}</div></section></div>;
}

function PromptSettingsCard({ currentPrompt, promptKey, promptOption, defaults, onPromptKey, onPromptChange, onRestore }: { currentPrompt: string; promptKey: PromptKey; promptOption: SelectOption & { key: PromptKey; hint: string }; defaults: PromptSettings | null; onPromptKey: (key: PromptKey) => void; onPromptChange: (value: string) => void; onRestore: () => void }) {
  return <section className="surface p-4"><div className="mb-3"><h2 className="text-sm font-semibold">System prompts</h2><p className="mt-1 text-xs text-muted-foreground">These instructions are shared by Ollama and llama.cpp. Dynamic content and structured-response rules remain protected.</p></div><label className="block max-w-xl text-xs font-medium text-muted-foreground">Prompt task<StyledSelect className="mt-1" value={promptKey} onChange={(value) => onPromptKey(value as PromptKey)} options={promptOptions} placeholder="Choose prompt" ariaLabel="Prompt task" /></label><p className="mt-2 text-xs text-muted-foreground">{promptOption.hint}</p><textarea value={currentPrompt} onChange={(event) => onPromptChange(event.target.value)} spellCheck={false} className="field mt-3 min-h-64 resize-y font-mono text-xs leading-relaxed" aria-label={`${promptOption.label} system prompt`} /><div className="mt-3 flex justify-end"><button onClick={onRestore} disabled={!defaults} className="app-button app-button-outline"><RotateCcw className="size-4" />Restore default</button></div></section>;
}

function AssignmentGroup({ title, active, models, translation, vision, onAssign, emptyText }: { title: string; active: boolean; models: ModelInfo[]; translation: string; vision: string; onAssign: (role: ModelRole, id: string) => void; emptyText: string }) { const textOptions = modelOptions(models, false); const visionOptions = modelOptions(models, true); return <div className="rounded-lg border bg-muted/20 p-3"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-medium">{title}</p>{active && <span className="rounded-full bg-foreground px-2 py-0.5 text-[.65rem] font-semibold text-background">Active</span>}</div><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Translation model<StyledSelect className="mt-1" value={translation} onChange={(id) => onAssign("translation", id)} options={textOptions} placeholder="No translation model" ariaLabel={`${title} translation model`} /></label><label className="text-xs font-medium text-muted-foreground">OCR / Vision model<StyledSelect className="mt-1" value={vision} onChange={(id) => onAssign("vision", id)} options={visionOptions} placeholder="No OCR model" ariaLabel={`${title} OCR model`} /></label></div>{models.length === 0 && <p className="mt-3 text-xs text-muted-foreground">{emptyText}</p>}</div>; }
function DownloadProgress({ progress, className = "" }: { progress: NonNullable<ReturnType<typeof useOperationStore.getState>["progress"]>; className?: string }) { const percentage = progress.total > 0 ? Math.min(100, Math.round((progress.completed / progress.total) * 100)) : 0; const remaining = progress.total > progress.completed ? progress.total - progress.completed : 0; const eta = progress.speedBytesPerSecond > 0 && remaining > 0 ? Math.ceil(remaining / progress.speedBytesPerSecond) : 0; return <div className={`rounded-md border bg-muted/20 p-3 ${className}`}><div className="flex items-center justify-between gap-3 text-xs"><span className="min-w-0 truncate font-medium">{progress.message}</span>{progress.total > 0 && <span className="font-mono text-muted-foreground">{percentage}%</span>}</div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-foreground transition-[width] duration-200" style={{ width: `${percentage}%` }} /></div><div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 font-mono text-[.68rem] text-muted-foreground"><span>{bytes(progress.completed)}{progress.total > 0 ? ` / ${bytes(progress.total)}` : ""}</span>{progress.speedBytesPerSecond > 0 && <span>{bytes(progress.speedBytesPerSecond)}/s</span>}{eta > 0 && <span>~{formatDuration(eta)} remaining</span>}<span className="uppercase">{progress.stage}</span></div></div>; }
function modelOptions(models: ModelInfo[], visionOnly: boolean): SelectOption[] { const available = visionOnly ? models.filter((model) => model.supportsVision) : models; return [{ value: "", label: "No model selected" }, ...available.map((model) => ({ value: model.id, label: `${model.name || model.id}${model.parameters ? ` · ${model.parameters}` : ""}` }))]; }
function assignmentFrom(model: ModelInfo): ModelAssignment { return { id: model.id, path: model.path, projectionPath: model.projectionPath, supportsVision: model.supportsVision }; }
function runtimeLabel(item: { version: string; cpuInstalled: boolean; cudaInstalled: boolean }) { return `${item.version} · ${[item.cpuInstalled && "CPU", item.cudaInstalled && "CUDA"].filter(Boolean).join(" + ")}`; }
function formatDuration(seconds: number) { return seconds >= 60 ? `${Math.ceil(seconds / 60)} min` : `${seconds}s`; }
function ModelRow({ model, action }: { model: ModelInfo; action: ReactNode }) { return <div className="flex items-center gap-2 rounded-md border px-3 py-2"><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{model.name || model.id}</p><p className="text-xs text-muted-foreground">{model.parameters || bytes(model.size)} {model.quantization ? `· ${model.quantization}` : ""}</p></div>{action}</div>; }
function LoadingLine() { return <div className="flex items-center gap-2 py-2 text-sm text-muted-foreground"><Loader2 className="size-4 animate-spin" />Loading…</div>; }
function message(reason: unknown, fallback: string) { return reason instanceof Error ? reason.message : fallback; }
